{
  "name": "hashpress-opencode",
  "version": "0.7.2",
  "description": "OpenCode plugin: sectioned-prose compaction handoffs with anchored summary merge, FlashHash request-view and native-arm assist, request-clone pruning for faster compact gen, autocontinue storm control, a token-efficient ask_advisor tool, and a TUI /hashpress flashhash-only command. Does not set the compaction model.",
  "license": "MIT",
  "author": "Jared Boynton",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jaredboynton/hashpress-opencode.git"
  },
  "homepage": "https://github.com/jaredboynton/hashpress-opencode#readme",
  "bugs": {
    "url": "https://github.com/jaredboynton/hashpress-opencode/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "compaction",
    "context",
    "hashpress",
    "transponder"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js",
      "default": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "package.json"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.json",
    "test": "bun test ./test",
    "prepack": "npm run build",
    "verify:pack": "bun run scripts/verify-pack.mjs"
  },
  "devDependencies": {
    "@types/node": "^26.1.1",
    "bun-types": "^1.3.14",
    "typescript": "^5.9.3"
  },
  "dependencies": {
    "@opencode-ai/plugin": ">=1.2.27"
  }
}
